-- Table: inventory_valuation_detail
-- Source: accounting_admin_db.sql (5. Inventory)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS inventory_valuation_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    valuation_id         BIGINT NOT NULL REFERENCES inventory_valuation(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    product_id           BIGINT NOT NULL REFERENCES masterdata_product(id),
    quantity             NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    uom_id               BIGINT NOT NULL REFERENCES masterdata_uom(id),
    unit_cost            NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
    total_value          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_value >= 0),
    inventory_account_id BIGINT REFERENCES masterdata_coa(id),
    UNIQUE (valuation_id, line_number)
);
